  [['معنى ان', 'كأن', 'لعل', 'ليت'], 'إنَّ تفيدُ التأكيد، وكأنَّ التشبيه، وليتَ التمنّي، ولعلَّ الترجّي. (ص٩٣)'],
  [['النسخ', 'معنى النسخ'], 'النَّسخُ: إزالةُ حكمِ المبتدأ والخبر وتغييرُه لفظًا ومعنًى. (ص٨٧)'],
  [['علامات النصب', 'نصب المثنى', 'نصب الجمع'], 'علاماتُ نصبِ الأسماء: الفتحة (المفرد وجمع التكسير)، الألف (الأسماء الخمسة)، الياء (المثنّى وجمع المذكّر السالم)، الكسرة (جمع المؤنّث السالم). (ص٩٢)'],
  [['الاشتقاق', 'المشتقات'], 'الاشتقاقُ: استحداثُ كلمةٍ أخذًا من كلمةٍ أخرى للتعبيرِ بها عن معنًى جديدٍ يناسبُ المعنى الحرفيَّ للكلمةِ المأخوذِ منها. (ص٩٩)'],
  [['اسم الفاعل', 'فاعل'], 'اسمُ الفاعل: اسمٌ مشتقٌّ من الفعلِ يدلُّ على مَن وقعَ منه الفعلُ أو اتّصفَ به، وزنُه من الثلاثيّ (فاعِل) مثل: كاتِب، ظافِر. (ص١٠١)'],
  [['اسم المفعول', 'مفعول'], 'اسمُ المفعول: اسمٌ مشتقٌّ من الفعلِ يدلُّ على مَن وقعَ عليه الفعل، وزنُه من الثلاثيّ (مَفعُول) مثل: مكتوب، منصور. (ص١٠١)'],
  [['الميزان الصرفي', 'الوزن', 'فعل'], 'الميزانُ الصرفيّ طريقةٌ لوزنِ الكلمات بحروف (ف ع ل): الفاءُ تقابلُ الحرفَ الأوّل، والعينُ الثاني، واللامُ الثالث، وما زادَ يزيدُ في الميزان. (ص١٠١)'],
  [['اسم الالة', 'اوزان اسم الالة'], 'اسمُ الآلة: اسمٌ مشتقٌّ من الفعلِ الثلاثيّ للدلالةِ على الأداةِ التي يؤدّى بها الفعل. أوزانُه: مِفعال، مِفعَل، مِفعَلة، فاعِلة، فعّال، فعّالة، فاعول. ومنه جامدٌ سماعيّ مثل: سكّين، قلم، فأس، رمح. (ص١٠٧)'],
  [['خط النسخ', 'قواعد الخط'], 'من قواعدِ خطِّ النسخ: رؤوسُ (ف، ق، و، م، هـ، ص، ض، ط، ظ) مفتوحة، والنقاطُ منفردة، و(ع، غ، م) مطموسةٌ وسطَ الكلمة، وبعضُ الحروفِ ينزلُ تحتَ السطر مثل (ر، ز، ن، و، ل، م). (ص١٠٩–١١٠)'],
  [['حافظ ابراهيم', 'الشاعر', 'شاعر النيل'], 'حافظ إبراهيم شاعرٌ مصريّ لُقّبَ بشاعرِ النيل، وُلِدَ عام ١٢٨٨هـ، وله ديوانٌ من جزأين، توفّيَ عام ١٣٥١هـ. (ص١١٧)'],
  [['عمر', 'رسول كسرى', 'القصيدة'], 'تحكي الأبياتُ دهشةَ رسولِ كسرى حين رأى عمرَ بنَ الخطّاب رضي الله عنه نائمًا تحتَ ظلِّ الشجرِ بلا حرس، فقال: «عدلتَ فأمنتَ فنمتَ يا عمر». (ص١١٦، ١١٩)'],
  [['راع', 'عطلا', 'الدوح', 'الثرى', 'معاني الكلمات'], 'راعَ: أدهشَ · عُطْلًا: خاليًا من المال والسلاح والحرس · الجلالة: المهابة · الثّرى: التراب · الدَّوح: الشجرُ العظيم · هانَ: صغُرَ · قريرُ العين: مرتاحُ البال. (ص١١٧)']
